function W({registerIndicator:v,nulls:r}){v({id:"oa-kdj",name:"KDJ",category:"Oscillators",placement:"pane",inputs:[{key:"length",type:"number",label:"Length",default:9,min:1,max:500,step:1},{key:"signal",type:"number",label:"Signal",default:3,min:1,max:50,step:1}],plots:[{key:"k",type:"line",title:"K",style:{color:"#2962ff",lineWidth:2}},{key:"d",type:"line",title:"D",style:{color:"#ff5252",lineWidth:2}},{key:"j",type:"line",title:"J",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:80,title:"Overbought K",color:"#ff5252",dashed:!0},{price:70,title:"Overbought D",color:"#ff9800",dashed:!0},{price:50,title:"Midline",color:"#787b86"},{price:30,title:"Oversold D",color:"#00e676",dashed:!0},{price:20,title:"Oversold K",color:"#4caf50",dashed:!0}],calc(i,d){const g=Math.max(1,Math.min(500,Math.floor(Number(d.length)||9))),j=Math.max(1,Math.min(50,Math.floor(Number(d.signal)||3))),o=i.length,u=1/j,h=1-u,y=new Array(o).fill(NaN),M=new Array(o).fill(NaN),w=new Array(o).fill(NaN);let N=!0,k=!0,m=1,p=1,n=0,a=0,c=50,s=50;const t=[],l=[];for(let e=0;e<o;e++){const x=i[e].high,D=i[e].low,K=i[e].close;if(Number.isFinite(x)&&Number.isFinite(D)&&Number.isFinite(K)){for(;t.length>0&&t[0]<=e-g;)t.shift();for(;l.length>0&&l[0]<=e-g;)l.shift();for(;t.length>0&&i[t[t.length-1]].high<=x;)t.pop();for(;l.length>0&&i[l[l.length-1]].low>=D;)l.pop();t.push(e),l.push(e);const A=i[t[0]].high,b=i[l[0]].low,O=A-b,F=O>0?100*(K-b)/O:50;if(n=u*F+h*n,a=u*n+h*a,N){m*=h;const f=1/(1-m);c=Math.max(0,Math.min(100,f*n)),N=m>1e-10}else c=Math.max(0,Math.min(100,n));if(k){p*=h;const f=1/(1-p);s=Math.max(0,Math.min(100,f*a)),k=p>1e-10}else s=Math.max(0,Math.min(100,a))}y[e]=c,M[e]=s,w[e]=3*c-2*s}return{k:r(y),d:r(M),j:r(w)}}})}export{W as default};
